/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"ableton-level-2","number":2,"title":"Live Concepts Browser Files","skillBand":"Textbook","duration":"From the course textbook","summary":"- Gate ID: ableton-gate-a - Prerequisites: Module 1 (Sections 1.1–1.4) and Module 2 (Sections 2.1–2.3)","modules":[{"id":"ableton-m-GA-1","code":"GA","title":"Readiness Assessment: Gate A","blurb":"- Gate ID: ableton-gate-a - Prerequisites: Module 1 (Sections 1.1–1.4) and Module 2 (Sections 2.1–2.3)","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-gate-a","title":"Section overview","blocks":[{"type":"step","title":"Operational Competency & Studio Foundation","blocks":[{"type":"heading","text":"Assessment Overview","level":3},{"type":"list","items":["<strong>Gate ID:</strong> <code>ableton-gate-a</code>","<strong>Prerequisites:</strong> Module 1 (Sections 1.1–1.4) and Module 2 (Sections 2.1–2.3)","<strong>Evaluation Format:</strong> Deterministic Self-Assessment Protocol (Direct execution in Ableton Live 12 Standard)","<strong>Objective:</strong> Verify absolute studio bootstrap readiness, ASIO subsystem stability, browser mastery, and file hygiene before advancing to sequencing and timeline composition."],"ordered":false},{"type":"heading","text":"Verification Drill Protocol","level":3},{"type":"prose","html":"Execute the following five operational drills in Ableton Live 12 Standard:"},{"type":"heading","text":"Drill 1: Edition & Hardware Interface Verification","level":4},{"type":"list","items":["Open <code>Help -&gt; About Live</code>. Verify the application displays <strong>Ableton Live 12 Standard</strong>.","Open <code>Preferences -&gt; Audio</code> (<code>Ctrl+,</code>).","Verify that <strong>Driver Type</strong> is set strictly to <code>ASIO</code>.","Verify that the <strong>Audio Device</strong> reflects your installed low-latency hardware interface or designated virtual ASIO bus.","Set buffer size to <code>256 Samples</code> (or lower) at <code>48,000 Hz</code> (or <code>44,100 Hz</code>). Turn on the Test Tone at <code>-18 dB</code>. Verify clean playback."],"ordered":true},{"type":"heading","text":"Drill 2: Template & Project Instantiation","level":4},{"type":"list","items":["In the Browser, navigate to <code>Templates</code> and open your <code>Studio_Standard_Template</code>.","Confirm that the Set opens with:","Info View visible in the lower-left corner (<code>?</code>).","Standard track assignments (Audio, Operator, Drift).","Return A (Reverb) and Return B (Delay) active.","Save the Set as <code>Gate_A_Verification_Project</code> inside a dedicated directory via <code>File -&gt; Save Live Set As...</code>."],"ordered":true},{"type":"heading","text":"Drill 3: Browser Taxonomic Retrieval","level":4},{"type":"list","items":["In the Browser, press <code>Ctrl+F</code> and retrieve <strong>Operator</strong>. Drag an instance onto a MIDI track.","In the Browser, apply a taxonomic filter: <code>Drums -&gt; One-Shot -&gt; Electronic -&gt; Kick</code>.","Select any kick sample and press <code>Ctrl+Shift+F</code> to execute a <strong>Sound Similarity Search</strong>.","Confirm that neural similarity results populate the Content Pane. Drag one result onto an audio track."],"ordered":true},{"type":"heading","text":"Drill 4: The Session Priority Override & Restoration Test","level":4},{"type":"list","items":["On the audio track, place an audio clip in Arrangement View at bar <code>1.1</code>.","On the same audio track, place an audio clip in Session View Slot 1.","Start Arrangement playback (<code>Spacebar</code>).","While playback is active, switch to Session View (<code>Tab</code>) and launch the Session clip.","Verify that:","The audio track switches immediately to playing the Session clip.","The <strong>Back to Arrangement</strong> button in the Control Bar / Session mixer lights up orange.","Press <code>F10</code>. Verify that the audio track instantly returns to the Arrangement timeline."],"ordered":true},{"type":"heading","text":"Drill 5: Archival Hygiene (\"Collect All and Save\")","level":4},{"type":"list","items":["Execute <code>File -&gt; Collect All and Save</code>.","Ensure <em>Files from elsewhere on this computer</em> is checked <code>Yes</code>.","Click <code>OK</code>.","Open Windows File Explorer and navigate to your <code>Gate_A_Verification_Project</code> directory.","Verify that <code>Samples/Imported/</code> exists and physically contains the audio sample used in Drill 3."],"ordered":true}]}],"minutes":8},{"id":"ableton-gate-a-2","title":"A Verification Checklist & Sign-Off","blocks":[{"type":"step","title":"A Verification Checklist & Sign-Off","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[GATE A PASS CRITERIA]\n[ ] Drill 1 Complete: Live 12 Standard verified; ASIO driver operating cleanly without dropouts.\n[ ] Drill 2 Complete: Custom template loaded with correct I/O, returns, and Info View.\n[ ] Drill 3 Complete: Operator instantiated; Sound Similarity search successfully executed.\n[ ] Drill 4 Complete: Session override and Back to Arrangement (F10) demonstrated.\n[ ] Drill 5 Complete: Collect All and Save verified on disk.</pre>"},{"type":"prose","html":"<strong>Status:</strong> When all criteria are checked, the student is certified for Module 3: Session View."}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-2-1-2","code":"2.1","title":"Live Concepts, Browser & File Hygiene","blurb":"- Section ID: ableton-sec-2-1 - Lessons Included: ableton-l2-1-1, ableton-l2-1-2, ableton-l2-1-3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l2-1-1","title":"Section overview","blocks":[{"type":"step","title":"Section 2.1 — The Live Mental Model & Structural Architecture","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-2-1</code>","<strong>Lessons Included:</strong> <code>ableton-l2-1-1</code>, <code>ableton-l2-1-2</code>, <code>ableton-l2-1-3</code>","<strong>Target Skill Band:</strong> Foundation Systems Architecture","<strong>Manual Spine References:</strong> Chapter 3 (<em>Live Concepts: 3.1–3.21</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard (Dual-View Summing Architecture)"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Navigate the Dual-View Architecture:</strong> Articulate how the <strong>Session View</strong> (non-linear clip launcher) and <strong>Arrangement View</strong> (linear timeline) represent two simultaneous operational interfaces of a single underlying audio engine.","<strong>Apply the Session Override &amp; Back to Arrangement Rule:</strong> Analyze how launching a Session clip interrupts Arrangement timeline playback on that specific track, and execute the <strong>Back to Arrangement</strong> command (<code>F10</code> / lit button) to restore timeline authority.","<strong>Map the Core Nouns of Live:</strong> Distinguish tracks, clip slots, clips, devices, signal chains, mixer strips, and global Control Bar/Status Bar elements.","<strong>Identify Scale-Aware Systems &amp; Racks:</strong> Recognize global Scale controls in the Control Bar and identify how Device View accommodates native instruments, effects, and multi-chain Racks."],"ordered":true}]}],"minutes":8},{"id":"ableton-l2-1-1-2","title":"2.1.1: The Control Bar, Status Bar & Dual Views","blocks":[{"type":"step","title":"1.1 The Control Bar Global Navigation Center","blocks":[{"type":"prose","html":"Located at the top of the interface, the <strong>Control Bar</strong> houses all global transport, timing, scale, and performance monitoring functions:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────────────────────────────────┐\n│                                       CONTROL BAR ARCHITECTURE                                          │\n├───────────────────┬──────────────┬───────────────┬───────────────┬───────────────┬──────────────────────┤\n│ 1. VIEW SELECTOR  │ 2. TEMPO/SYNC│ 3. SCALE / KEY│ 4. TRANSPORT  │ 5. RECORDING  │ 6. PERFORMANCE &amp; CPU │\n├───────────────────┼──────────────┼───────────────┼───────────────┼───────────────┼──────────────────────┤\n│ • Browser Toggle  │ • BPM (120.0)│ • Scale Toggle│ • Play (Space)│ • Arr. Record │ • MIDI In/Out LEDs   │\n│ • Session/Arr.    │ • Tap Tempo  │ • Root Key (C)│ • Stop (Space)│ • Session Rec │ • Sample Rate (48k)  │\n│   Selector (Tab)  │ • Time Sig   │ • Scale (Maj) │ • Locators    │ • Capture MIDI│ • CPU Meter (12%)    │\n│ • Info View (?)   │ • Metronome  │ • Scale Scope │ • Loop Braces │ • Overdub (+) │ • Focus Outline      │\n└───────────────────┴──────────────┴───────────────┴───────────────┴───────────────┴──────────────────────┘</pre>"}]},{"type":"step","title":"1.2 The Status Bar (Bottom Margin)","blocks":[{"type":"prose","html":"The <strong>Status Bar</strong> runs along the bottom margin of the application window:"},{"type":"list","items":["<strong>Parameter Readout:</strong> Displays exact numerical values, bar.beat.sixteenth locations, and contextual tooltips.","<strong>Background Processing Indicator:</strong> Displays analysis progress for sample decoding, waveform generation, and Sound Similarity vector calculations with a pause/resume control.","<strong>MIDI Note Inspector:</strong> When a note is selected in the MIDI Note Editor, the Status Bar displays its exact pitch, start time, duration, velocity, and probability percentage."],"ordered":false}]},{"type":"step","title":"1.3 Dual Views of a Single Set: Session vs. Arrangement","blocks":[{"type":"prose","html":"A Live Set (<code>.als</code>) is a unified database of tracks, mixer settings, and device parameters. Live provides two distinct interfaces for visualizing and manipulating this data:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                 DUAL-VIEW ENGINE ARCHITECTURE (ONE LIVE SET)                │\n├─────────────────────────────────────────────────────────────────────────────┤\n│   SESSION VIEW (Non-Linear Matrix)       ARRANGEMENT VIEW (Linear Timeline) │\n│   ┌──────┬──────┬──────┐                 Track 1 (Drums)  [Clip A][Clip B]  │\n│   │Track1│Track2│Track3│                 Track 2 (Bass)   [  Clip A  ]      │\n│   ├──────┼──────┼──────┤                 Track 3 (Synths) [      Clip A      ]│\n│   │Clip 1│Clip 1│Clip 1│◄── Scene 1      Timeline: 1.1 ───► 17.1 ───► 33.1  │\n│   │Clip 2│Clip 2│Clip 2│◄── Scene 2                                         │\n│   └──────┴──────┴──────┘                 • Horizontal Time Axis (Left-&gt;Right│\n│   • Vertical Track Columns               • Fixed Chronological Structure    │\n│   • Real-Time Jamming &amp; Improvisation    • Linear Composition &amp; Mastering   │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>View Switching:</strong> Press <code>Tab</code> to alternate between Session View and Arrangement View.","<strong>Dual-Window Mode:</strong> Press <code>Ctrl+Shift+W</code> (or <code>Window -&gt; Second Window</code>) to detach one view onto a secondary display monitor."],"ordered":false}]}],"minutes":8},{"id":"ableton-l2-1-2","title":"2.1.2: Tracks, Clips, Devices & The Priority Override Rule","blocks":[{"type":"step","title":"2.1 The Core Nouns of the Live Environment","blocks":[{"type":"list","items":["<strong>Tracks:</strong> Signal processing conduits. Session View displays tracks as vertical columns; Arrangement View displays them as horizontal lanes. A track processes either Audio or MIDI, hosts a chain of Devices, and terminates in a Mixer channel.","<strong>Clips:</strong> Discrete units of musical data. Audio clips reference digital audio files; MIDI clips contain note, velocity, pitch bend, and expression data.","<strong>Scenes:</strong> Horizontal rows across the Session View grid. Launching a scene triggers all clips across that row simultaneously.","<strong>Devices:</strong> Digital signal processors situated in the <strong>Device View</strong> at the bottom of the screen. Signal flows strictly left-to-right through the device chain."],"ordered":true},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                         TRACK SIGNAL FLOW TOPOLOGY                          │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [MIDI/Audio Clip] ──► [Device 1 (Inst)] ──► [Device 2 (FX)] ──► [Mixer]    │\n│                                                                     │       │\n│                                            ┌────────────────────────┴────┐  │\n│                                            ▼                             ▼  │\n│                                      [Send Buses A-L]              [Main Bus]\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"2.2 The Fundamental Priority Rule & \"Back to Arrangement\"","blocks":[{"type":"prose","html":"A single track <strong>can never play a Session clip and an Arrangement clip simultaneously</strong>."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                 THE SESSION OVERRIDE &amp; RESTORATION MECHANISM                │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  1. TIMELINE PLAYBACK (Arrangement in charge):                              │\n│     Arrangement clips play according to the song timeline position.         │\n│                                                                             │\n│  2. SESSION CLIP LAUNCH (Override Event):                                   │\n│     User launches a Session clip on Track 1.                                │\n│     -&gt; Track 1 immediately ceases playing its Arrangement timeline clips.   │\n│     -&gt; Track 1 plays the Session clip in a loop.                            │\n│     -&gt; Other tracks continue playing Arrangement timeline clips.            │\n│     -&gt; The \"Back to Arrangement\" button lights up ORANGE in Control Bar.   │\n│                                                                             │\n│  3. BACK TO ARRANGEMENT (Restoration Event):                                │\n│     User presses [F10] or clicks the Orange Back to Arrangement button.     │\n│     -&gt; Session clip playback disconnects.                                   │\n│     -&gt; Track 1 returns instantly to the active Arrangement timeline position│\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]}],"minutes":8},{"id":"ableton-l2-1-3","title":"2.1.3: Scale Awareness, Device View & Presets","blocks":[{"type":"step","title":"2.1.3: Scale Awareness, Device View & Presets","blocks":[{"type":"heading","text":"3.1 Global & Clip-Level Scale Awareness","level":4},{"type":"prose","html":"Live 12 integrates system-wide <strong>Scale Awareness</strong>:"},{"type":"list","items":["<strong>Control Bar Setting:</strong> Sets the project-wide default key and scale (e.g., C Natural Minor).","<strong>Clip Synchronization:</strong> New MIDI clips inherit the global scale. Inside the MIDI Note Editor, the <strong>Scale</strong> button highlights scale degrees on the piano roll or folds the display to hide out-of-scale notes.","<strong>Device Synchronization:</strong> Scale-aware devices and MIDI Tools (such as <em>Stacks</em>, <em>Arpeggiate</em>, and <em>Drift</em>) dynamically constrain generated notes to the selected scale."],"ordered":false},{"type":"heading","text":"3.2 Clip View vs. Device View","level":4},{"type":"prose","html":"The lower portion of the Live interface toggles between two specialized editors:"},{"type":"list","items":["<strong>Clip View (<code>Shift+Tab</code>):</strong> Displays the internal parameters of the currently selected clip (Warp markers, loop braces, launch settings, pitch/gain, and MIDI Note Editor).","<strong>Device View (<code>Shift+Tab</code>):</strong> Displays the signal chain of instruments, audio effects, and Max for Live devices on the selected track."],"ordered":false},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                   LOWER PANEL DUAL-FUNCTION ARCHITECTURE                    │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [Shift+Tab] toggles between:                                               │\n│                                                                             │\n│  CLIP VIEW (Clip Parameters &amp; Note/Sample Editor)                           │\n│  ┌────────────────────────────────────────────────────────────────────────┐ │\n│  │ Loop: [1.1.1 - 5.1.1] │ Scale: C Minor │ Piano Roll Grid / Audio Wave  │ │\n│  └────────────────────────────────────────────────────────────────────────┘ │\n│                                  ▲                                          │\n│                                  ▼ [Shift+Tab]                              │\n│  DEVICE VIEW (Signal Chain Processors)                                      │\n│  ┌───────────────┐  ┌──────────────────┐  ┌───────────────────────────────┐ │\n│  │ DRIFT (Synth) │─►│ CHORUS-ENSEMBLE  │─►│ DELAY                         │ │\n│  └───────────────┘  └──────────────────┘  └───────────────────────────────┘ │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Dual-View Navigation Protocol:</strong>","Open <code>Ableton-Course-Sandbox.als</code>.","Press <code>Tab</code> repeatedly to alternate between Session View and Arrangement View.","Press <code>Alt+1</code> to select Session View; press <code>Alt+2</code> to select Arrangement View.","<strong>Session Priority Override &amp; Back to Arrangement Drill:</strong>","In Arrangement View, drag your Drift MIDI clip across bars <code>1.1</code> to <code>9.1</code> on Track 1.","Start playback with <code>Spacebar</code>. Confirm timeline playback along the ruler.","While the timeline is playing, press <code>Tab</code> to switch to Session View.","Click the <strong>Launch Button</strong> on a different clip slot on Track 1.","Observe that the timeline continues moving, but Track 1 is now playing the looping Session clip.","Observe the <strong>Back to Arrangement</strong> button (an orange button with a play arrow inside horizontal lines) lit in the upper-right of the Session mixer / Control Bar.","Press <code>F10</code> (or click Back to Arrangement). Confirm that Track 1 immediately snaps back to timeline playback.","<strong>Clip View / Device View Toggle:</strong>","Click on the Drift track header.","Press <code>Shift+Tab</code>. Observe Device View showing the Drift synth panel.","Press <code>Shift+Tab</code> again. Observe Clip View showing the MIDI piano roll."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 2.0]\n[ ] Fluent in switching views using Tab, Alt+1, and Alt+2.\n[ ] Verified that launching a Session clip overrides Arrangement playback on that track only.\n[ ] Successfully restored timeline playback using the F10 shortcut.\n[ ] Toggled Clip View and Device View using Shift+Tab.\n[ ] Can identify Control Bar sections (Tempo, Scale, Transport, CPU) with Info View.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 3 (<em>Live Concepts: 3.1 Control Bar, 3.2 Status Bar, 3.6 Tracks and Scenes, 3.7 Routing, 3.8 Live Sets</em>).","<strong>Ableton Knowledgebase:</strong> <em>Session vs. Arrangement View Explained</em>, <em>Using Back to Arrangement</em>, <em>Scale Awareness in Live 12</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-2-2-3","code":"2.2","title":"Live Concepts, Browser & File Hygiene","blurb":"- Section ID: ableton-sec-2-2 - Lessons Included: ableton-l2-2-1, ableton-l2-2-2, ableton-l2-2-3, ableton-l2-2-4","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l2-2-1","title":"Section overview","blocks":[{"type":"step","title":"Section 2.2 — The Live 12 Browser & Metadata Search Engine","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-2-2</code>","<strong>Lessons Included:</strong> <code>ableton-l2-2-1</code>, <code>ableton-l2-2-2</code>, <code>ableton-l2-2-3</code>, <code>ableton-l2-2-4</code>","<strong>Target Skill Band:</strong> Library Asset Management &amp; Workflow Speed","<strong>Manual Spine References:</strong> Chapter 4 (<em>Working with the Browser: 4.1–4.10</em>), Chapter 3 (<em>Live Concepts: 3.4 Sound Similarity</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Browser Infrastructure"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Operate Browser Architecture:</strong> Navigate the multi-column browser, query assets via boolean search filters, utilize browser history navigation, and save persistent <strong>Custom Labels</strong>.","<strong>Implement Taxonomic Tagging:</strong> Apply factory and custom user tags using the <strong>Tag Editor</strong>, filter by multi-attribute intersection, and utilize <strong>Quick Tags</strong> for rapid sample categorization.","<strong>Manage Asset Repositories:</strong> Distinguish between the read-only <strong>Core Library</strong>, installed <strong>Packs</strong>, the mutable <strong>User Library</strong>, external <strong>Places</strong>, <strong>Current Project</strong>, and <strong>Ableton Cloud</strong>.","<strong>Deploy Sound Similarity Search:</strong> Execute neural audio similarity searches (<code>Ctrl+Shift+F</code>) on drum samples and synth presets, swap similar samples within Simpler/Drum Racks, and manage the background neural analysis engine."],"ordered":true}]}],"minutes":8},{"id":"ableton-l2-2-1-2","title":"2.2.1: Search Architecture, Custom Labels & History","blocks":[{"type":"step","title":"1.1 The Multi-Column Browser Topology","blocks":[{"type":"prose","html":"The Live 12 browser is organized into three primary operational columns:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                           LIVE 12 BROWSER TOPOLOGY                          │\n├───────────────────┬───────────────────────────────┬─────────────────────────┤\n│ 1. SIDEBAR        │ 2. FILTER &amp; TAG PANE          │ 3. CONTENT RESULTS PANE │\n├───────────────────┼───────────────────────────────┼─────────────────────────┤\n│ • Collections (7) │ [Filters Toggle (Ctrl+Alt+F)] │ Kick_Deep_808.wav       │\n│ • Categories      │ ┌───────────────────────────┐ │ Kick_Acoustic_Punch.wav │\n│   - Sounds        │ │ Content: [Drums] [One-Shot│ │ Kick_Analog_Click.wav   │\n│   - Drums         │ │ Character: [Warm] [Punchy]│ │                         │\n│   - Instruments   │ └───────────────────────────┘ │                         │\n│   - Audio Effects │                               │                         │\n│ • Places          │ Custom Saved Labels:          │                         │\n│   - User Library  │ • \"Analog Sub Kicks\"          │ Preview: [ &gt; ] Volume:  │\n│   - Current Proj. │ • \"Course Templates\"          │ [==========|====]       │\n└───────────────────┴───────────────────────────────┴─────────────────────────┘</pre>"},{"type":"list","items":["<strong>Toggle Shortcut:</strong> <code>Ctrl+Alt+B</code> opens/closes the browser sidebar.","<strong>Search Query Focus:</strong> Press <code>Ctrl+F</code> to immediately place cursor focus into the search bar."],"ordered":false}]},{"type":"step","title":"1.2 Search Syntax & Custom User Labels","blocks":[{"type":"list","items":["<strong>Query Mechanics:</strong> Search indexing matches file names, folder paths, metadata tags, and device types.","<strong>Saving Custom Searches (Custom Labels):</strong> When a specific search string and filter combination is executed (e.g., <code>Drums -&gt; One-Shot -&gt; Electronic -&gt; Punchy</code>), clicking the <strong>Add Label (+)</strong> icon at the bottom of the sidebar creates a persistent, one-click smart folder in the sidebar.","<strong>Browser History:</strong> Navigation buttons (<code>&lt;</code> and <code>&gt;</code>) at the top of the browser allow instant backward/forward traversal through recent search states and directory locations."],"ordered":false}]}],"minutes":8},{"id":"ableton-l2-2-2","title":"2.2.2: Filters, Factory Tags & The Tag Editor","blocks":[{"type":"step","title":"2.1 Live 12 Taxonomic Metadata Architecture","blocks":[{"type":"prose","html":"Live 12 replaces legacy hierarchical folder crawling with a relational tagging engine:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                       TAG TAXONOMY CLASSIFICATION                           │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  CATEGORY         │ ATTRIBUTES                                              │\n├───────────────────┼─────────────────────────────────────────────────────────┤\n│  Content Type     │ Sample, Loop, One-Shot, Device Preset, Max Device, Groov│\n│  Instrument Type  │ Synth Lead, Bass, Acoustic Drums, Piano, Mallet, Pad    │\n│  Audio Character  │ Bright, Dark, Warm, Clean, Distorted, Lo-Fi, Aggressive │\n│  Technical Format │ 24-bit WAV, FLAC, AIFF, MIDI Clip (.alc), Device (.adv) │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"2.2 The Tag Editor & Quick Tagging","blocks":[{"type":"list","items":["<strong>Opening the Tag Editor:</strong> Click the <strong>Edit</strong> button in the Filter header.","<strong>Creating Custom Tags:</strong> Users can create custom tag categories (e.g., <code>Project Name</code>, <code>Tracking Room</code>, <code>Hardware Source</code>) and assign custom tags.","<strong>Assigning Tags:</strong> Select single or multiple files in the Content Pane, and check the corresponding tag boxes in the Tag Editor.","<strong>Quick Tags:</strong> When enabled, hovering over items displays small circular tag prompts for one-click assignment."],"ordered":false}]}],"minutes":8},{"id":"ableton-l2-2-3","title":"2.2.3: Asset Storage Repositories","blocks":[{"type":"step","title":"3.1 Repository Definitions & Boundaries","blocks":[{"type":"prose","html":"To prevent missing sample references, engineers must understand the distinct operational boundaries of each browser category:"},{"type":"table","headers":["Repository Name","Read/Write Status","File System Location","Operational Role"],"rows":[["<strong>Core Library</strong>","Read-Only","<code>C:\\ProgramData\\Ableton\\...\\Core Library</code>","Factory devices, stock presets, and default building blocks."],["<strong>Packs</strong>","Read-Only","User-Configured Pack Directory","Installed Ableton sound packs (38+ GB in Standard)."],["<strong>User Library</strong>","Read / Write","User Documents Folder","User presets (<code>.adv</code>), custom Racks (<code>.adg</code>), default Sets, and personal samples."],["<strong>Current Project</strong>","Read / Write","Active Live Project Folder","Samples, recordings, and clips associated exclusively with the open Set."],["<strong>Places</strong>","Read / Write","External Hard Drives / Directories","Direct symlinks to external sample libraries and sound effect archives."],["<strong>Ableton Cloud</strong>","Cloud Synced","Ableton Server Storage","Transport conduit for Note/Move iOS/Hardware sketches into desktop Live."]],"caption":null}]}],"minutes":8},{"id":"ableton-l2-2-4","title":"2.2.4: Previewing & Sound Similarity Search","blocks":[{"type":"step","title":"2.2.4: Previewing & Sound Similarity Search","blocks":[{"type":"heading","text":"4.1 Non-Destructive Previewing","level":4},{"type":"list","items":["<strong>Audition Engine:</strong> Clicking a sample in the browser triggers the raw audio preview player.","<strong>Raw / In-Tempo Preview:</strong> Toggle the <strong>Raw</strong> button at the bottom of the browser to hear samples without host tempo warping, or disable Raw to preview loops stretched to match active session tempo.","<strong>Preview Gain:</strong> The horizontal blue fader at the bottom of the browser sets the dedicated audition volume level."],"ordered":false},{"type":"heading","text":"4.2 Neural Sound Similarity Engine","level":4},{"type":"prose","html":"Live 12 incorporates a local neural audio analysis engine that computes high-dimensional acoustic feature vectors for samples 60 seconds in length:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                     SOUND SIMILARITY SEARCH TOPOLOGY                        │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [Target Sample: \"Punchy_Snare_01.wav\"]                                     │\n│     │                                                                       │\n│     ├──► [Neural Acoustic Vector Extraction]                                │\n│     │                                                                       │\n│     └──► [Database Distance Matching (Cosine Similarity)]                   │\n│             │                                                               │\n│             ├── Result 1: \"Acoustic_Snare_Thud.wav\" (98% Match)             │\n│             ├── Result 2: \"Electro_Snare_Tight.wav\" (94% Match)             │\n│             └── Result 3: \"Analog_Clap_Snap.wav\"    (89% Match)             │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Executing Similarity Search:</strong> Select any drum hit or short sample in the browser and press <code>Ctrl+Shift+F</code> (or click the <strong>Show Similar Files</strong> icon).","<strong>Similar Sample Swapping:</strong> In <strong>Drum Rack</strong>, <strong>Simpler</strong>, or <strong>Drum Sampler</strong>, clicking the circular double-arrow icon cycles through neural similarity alternatives instantly while playing a rhythm in real time."],"ordered":false}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Tag Filtering &amp; Search Drill:</strong>","Open Browser (<code>Ctrl+Alt+B</code>). Press <code>Ctrl+Alt+F</code> to open the Filter Pane.","Click the <code>Drums</code> category, select <code>One-Shot</code> under Content Type, and select <code>Electronic</code> under Character.","Observe the results list filtering in real time.","<strong>Creating a Custom User Label:</strong>","Type <code>Operator</code> in the browser search bar (<code>Ctrl+F</code>). Select the <code>Instruments</code> category.","Click the <code>+</code> button in the sidebar next to <em>Labels</em>. Name the label <code>Core Synths</code>.","Clear the search. Click <code>Core Synths</code> in the sidebar and verify that Operator immediately populates the browser.","<strong>Executing Sound Similarity Search:</strong>","In the browser, navigate to <code>Drums -&gt; Kick</code> and select any standard kick sample.","Press <code>Ctrl+Shift+F</code>. Observe the browser transforming into the Sound Similarity result list, ranked by acoustic proximity.","Audition the top 5 results. Notice how the timbre, transient profile, and decay length closely mirror the reference file."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 2.1]\n[ ] Fluent with browser shortcuts: Ctrl+Alt+B (Show/Hide), Ctrl+F (Search), Ctrl+Alt+F (Filters).\n[ ] Successfully created and saved a Custom Label.\n[ ] Can define the difference between Core Library (read-only) and User Library (read/write).\n[ ] Executed Sound Similarity search with Ctrl+Shift+F and auditioned results.\n[ ] Configured browser preview volume to match studio listening level.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 4 (<em>Working with the Browser: 4.1–4.10</em>), Chapter 3 (<em>Live Concepts: 3.4 Sound Similarity</em>).","<strong>Ableton Knowledgebase:</strong> <em>The Live 12 Browser &amp; Tags FAQ</em>, <em>Using Collections in Live</em>, <em>How Sound Similarity Search Works</em>, <em>The User Library vs. Core Library</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-2-3-4","code":"2.3","title":"Live Concepts, Browser & File Hygiene","blurb":"- Section ID: ableton-sec-2-3 - Lessons Included: ableton-l2-3-1, ableton-l2-3-2, ableton-l2-3-3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l2-3-1","title":"Section overview","blocks":[{"type":"step","title":"Section 2.3 — Managing Files, Live Sets & Project Hygiene","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-2-3</code>","<strong>Lessons Included:</strong> <code>ableton-l2-3-1</code>, <code>ableton-l2-3-2</code>, <code>ableton-l2-3-3</code>","<strong>Target Skill Band:</strong> Professional File System Architecture &amp; Project Archiving","<strong>Manual Spine References:</strong> Chapter 5 (<em>Managing Files and Sets: 5.1–5.11</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Project &amp; File Management Infrastructure"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Identify Audio &amp; Metadata File Formats:</strong> Differentiate between digital audio samples, Ableton analysis files (<code>.asd</code>), raw MIDI files (<code>.mid</code>), Live Clip presets (<code>.alc</code>), and Live Set files (<code>.als</code>).","<strong>Implement Structural Project Hierarchies:</strong> Distinguish a standalone Live Set (<code>.als</code>) from a complete <strong>Live Project Folder</strong>, articulating why moving <code>.als</code> files outside of their parent Project breaks media references.","<strong>Execute Non-Destructive Archiving via \"Collect All and Save\":</strong> Apply the <strong>Collect All and Save</strong> command to consolidate external audio media, Max for Live assets, and samples directly into the Project container.","<strong>Resolve Broken File References:</strong> Utilize the <strong>Automatic and Manual File Search &amp; Relink</strong> tools to repair missing sample paths across storage volumes.","<strong>Construct Production Template Sets:</strong> Build and set custom user <strong>Default Sets</strong> and <strong>Template Sets</strong> configured with optimal routing, gain staging, and return channels."],"ordered":true}]}],"minutes":8},{"id":"ableton-l2-3-1-2","title":"2.3.1: File Types & The Analysis Engine","blocks":[{"type":"step","title":"1.1 Live's Native File Formats Matrix","blocks":[{"type":"prose","html":"Ableton Live manages a specific ecosystem of binary and XML-based file containers:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                       ABLETON FILE FORMAT ANATOMY                           │\n├───────────────────┬─────────────────────────────────────────────────────────┤\n│ FILE EXTENSION    │ CONTENT &amp; FUNCTION                                      │\n├───────────────────┼─────────────────────────────────────────────────────────┤\n│ .als (Live Set)   │ Gzip-compressed XML document containing all track data, │\n│                   │ clip parameters, automation envelopes, and device state.│\n│                   │ DOES NOT CONTAIN RAW AUDIO SAMPLES.                     │\n├───────────────────┼─────────────────────────────────────────────────────────┤\n│ .asd (Analysis)   │ Binary metadata file storing Warp markers, transient    │\n│                   │ locations, sample peak cache, and default clip settings │\n│                   │ adjacent to the parent audio sample.                    │\n├───────────────────┼─────────────────────────────────────────────────────────┤\n│ .alc (Live Clip)  │ Self-contained preset referencing an audio or MIDI clip,│\n│                   │ including its associated device chain and automation.   │\n├───────────────────┼─────────────────────────────────────────────────────────┤\n│ .adg (Device Rack)│ Preset file saving the entire configuration of an       │\n│                   │ Instrument Rack, Audio Effect Rack, or Drum Rack.       │\n├───────────────────┼─────────────────────────────────────────────────────────┤\n│ .alp (Live Pack)  │ Compressed installer package containing samples, sets,  │\n│                   │ presets, and lessons for browser library installation.  │\n└───────────────────┴─────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"1.2 The Analysis File (.asd) Lifecycle","blocks":[{"type":"prose","html":"When Live imports any audio file (<code>.wav</code>, <code>.aif</code>, <code>.flac</code>), it analyzes the sample for transient peaks and tempo characteristics:"},{"type":"list","items":["<strong>Generation:</strong> An <code>.asd</code> file is generated immediately adjacent to the audio file in the file system.","<strong>Function:</strong> Stored analysis data accelerates subsequent loading and prevents re-analyzing waveforms every time a Set is opened.","<strong>Rule of Hygiene:</strong> Never delete <code>.asd</code> files mid-project. While deleting them does not corrupt raw audio, Live will be forced to regenerate transient maps and may reset custom warp marker placements."],"ordered":false}]}],"minutes":8},{"id":"ableton-l2-3-2","title":"2.3.2: Live Sets, Projects & Template Architecture","blocks":[{"type":"step","title":"2.1 The Project Hierarchy vs. The Standalone Live Set","blocks":[{"type":"prose","html":"A catastrophic error among novice engineers is copying only the <code>.als</code> file when transferring sessions to other computers:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                        CORRECT PROJECT HIERARCHY                            │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [Project Root Folder: \"Album_Track_01_Project\"]                            │\n│  ├── Album_Track_01_v1.als         &lt;- Live Set version 1                     │\n│  ├── Album_Track_01_v2.als         &lt;- Live Set version 2 (Alternative mix)   │\n│  ├── Ableton Project Info/                                                  │\n│  │   └── Project8.cfg              &lt;- Project-level index configuration     │\n│  ├── Backup/                                                                │\n│  │   ├── Album_Track_01_v1 [date].als &lt;- Automatic 10-tier rolling backups  │\n│  └── Samples/                                                               │\n│      ├── Recorded/                 &lt;- Audio tracked directly into the Set   │\n│      ├── Processed/                &lt;- Bounced, reversed, or consolidated audio│\n│      └── Imported/                 &lt;- Samples pulled via Collect All &amp; Save │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"2.2 Template Sets & Default Configurations","blocks":[{"type":"list","items":["<strong>Default Set (<code>Settings -&gt; File &amp; Folder -&gt; Save Current Set as Default</code>):</strong> Governs the initial state of Live when launching <code>Ctrl+N</code>.","<strong>Template Sets (<code>File -&gt; Save Set as Template</code>):</strong> Specialized configurations (e.g., <em>Tracking 16-Channel Live Band</em>, <em>Sound Design Sandbox</em>, <em>Stereo Mixing Bus</em>) accessible directly in the Browser under <code>Templates</code>."],"ordered":true}]}],"minutes":8},{"id":"ableton-l2-3-3","title":"2.3.3: Collect All and Save & Missing File Remediation","blocks":[{"type":"step","title":"2.3.3: Collect All and Save & Missing File Remediation","blocks":[{"type":"heading","text":"3.1 The Collect All and Save Protocol","level":4},{"type":"prose","html":"When external audio files are dragged into Live from external hard drives, desktop folders, or network shares, the <code>.als</code> merely stores file system pointers. If the external drive is disconnected, the Set will fail to load the media."},{"type":"prose","html":"To consolidate all dependencies into the Project folder:"},{"type":"list","items":["Navigate to <code>File -&gt; Collect All and Save</code>.","Configure the consolidation dialogue:"],"ordered":true},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                        COLLECT ALL AND SAVE DIALOGUE                        │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  Specify which media files should be copied into the Project:               │\n│                                                                             │\n│  [x] Files from elsewhere on this computer -&gt; YES (Consolidates OS samples) │\n│  [x] Files from other Projects             -&gt; YES (Prevents cross-proj ties)│\n│  [x] Files from User Library               -&gt; YES (Ensures portable presets)│\n│  [ ] Files from Factory Packs              -&gt; NO  (Avoids bloat if packs ok)│\n│  [x] Max for Live devices                  -&gt; YES (Preserves custom patchers)\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"heading","text":"3.2 Resolving Missing Files","level":4},{"type":"prose","html":"If a Set opens with an orange warning bar reading <em>\"Media files are missing\"</em>:"},{"type":"list","items":["Click the status bar prompt to open the <strong>Missing Media Files Panel</strong> on the right.","Select <strong>Automatic Search</strong>: Choose specific folder paths (<code>Places</code> or external drives) and enable <code>Search Project</code>, <code>Search Library</code>, and <code>Scan Deeply</code>.","If automatic search fails, use <strong>Manual Search</strong>: Drag the recovered audio file from the Browser Content Pane directly onto the missing sample slot in the Missing Files list."],"ordered":true}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Constructing a Standard Studio Template Set:</strong>","Create a clean Live Set (<code>Ctrl+N</code>).","Create 4 Audio Tracks: <code>Kick</code>, <code>Snare</code>, <code>Bass Audio</code>, <code>Vocal</code>.","Create 2 MIDI Tracks: <code>Operator Synth</code>, <code>Drift Poly</code>.","Insert a <strong>Utility</strong> device as the first insert on every track.","On <strong>Return Track A</strong>, insert a <strong>Reverb</strong> (100% Wet). Rename track to <code>REV</code>.","On <strong>Return Track B</strong>, insert a <strong>Delay</strong> (100% Wet). Rename track to <code>DLY</code>.","Press <code>?</code> to ensure Info View is active.","Navigate to <code>File -&gt; Save Set as Template...</code>. Name it <code>Studio_Standard_Template</code>.","<strong>Executing the \"Collect All and Save\" Drill:</strong>","Drag an external sample from Windows Desktop into Session Slot 1 on Audio Track 1.","Select <code>File -&gt; Collect All and Save</code>. Check <em>Files from elsewhere on this computer</em> to <code>Yes</code>.","Click <code>OK</code>. Open Windows File Explorer, navigate to the project directory, and confirm that the sample has been copied into <code>Samples/Imported/</code>."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 2.2]\n[ ] Defined .als, .asd, .alc, and .adg file types with precision.\n[ ] Built and saved a personalized Template Set to the User Library.\n[ ] Executed Collect All and Save and verified the physical population of Samples/Imported/.\n[ ] Understand how to initiate Automatic and Manual relinking in the Missing Media Files panel.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 5 (<em>Managing Files and Sets: 5.1–5.11</em>).","<strong>Ableton Knowledgebase:</strong> <em>Collect All and Save Best Practices</em>, <em>How to locate missing files</em>, <em>Default and Template Sets in Live 12</em>, <em>Managing Live Projects</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
